<script setup>
import { ref,computed } from 'vue';import { useRouter } from 'vue-router';import { studio,roles,getRole } from '../store.js';const router=useRouter(),roleId=ref(studio.state.value.preference),tab=ref('jd');const role=computed(()=>getRole(roleId.value));function prepare(){studio.call('savePreparation',{roleId:role.value.id,level:'校招',mode:'coaching',questionCount:4,jd:role.value.jd,resume:role.value.resume,resumeMode:'sample'});router.push('/interviews/new')}
</script>
<template><div class="page-heading"><div><p class="eyebrow">YOUR PREPARATION KIT</p><h1>好准备，从理解岗位开始。</h1><p class="muted">四岗位示例材料，可直接带入面试准备。</p></div></div><div class="filters"><label>岗位方向<select v-model="roleId"><option v-for="r in roles" :key="r.id" :value="r.id">{{r.title}}</option></select></label></div><div class="tabs"><button :class="{active:tab==='jd'}" @click="tab='jd'">岗位要求</button><button :class="{active:tab==='resume'}" @click="tab='resume'">经历示例</button><button :class="{active:tab==='topics'}" @click="tab='topics'">知识要点</button></div><section class="card library-content"><span class="badge">示例材料 · 非真实职位</span><h2>{{role.title}}</h2><template v-if="tab!=='topics'"><p class="lesson">{{tab==='jd'?role.jd:role.resume}}</p><div class="tags"><span v-for="skill in role.skills" :key="skill">{{skill}}</span></div><button class="button primary" @click="prepare">用于本次面试 →</button></template><div v-else><article v-for="q in role.questions" :key="q.id" class="list-row"><div><h3>{{q.topic}}</h3><p>{{q.lesson}}</p></div></article></div></section><section class="card legacy-entry"><div><h3>已有简历文件？</h3><p class="muted">登录真实账户，上传 PDF/DOCX，查看切割结果并确认入库。</p></div><RouterLink to="/resumes/real" class="button secondary">打开真实简历库 →</RouterLink></section></template>
